using System.IO.Pipes;using System.Text.Json;using GManager.Client.Domain;
using System.Security.AccessControl;using System.Security.Principal;namespace GManager.Client.Service;
public sealed class ClientWorker(ClientRuntime runtime,ILogger<ClientWorker> logger):BackgroundService {
 protected override async Task ExecuteAsync(CancellationToken stoppingToken){runtime.Recover();_ = RunPipe(stoppingToken);using var timer=new PeriodicTimer(TimeSpan.FromSeconds(10));do{await runtime.Refresh(stoppingToken);}while(await timer.WaitForNextTickAsync(stoppingToken));}
 async Task RunPipe(CancellationToken ct){while(!ct.IsCancellationRequested){try{await using var pipe=LocalPipeAcl.Create();await pipe.WaitForConnectionAsync(ct);var request=await JsonSerializer.DeserializeAsync<LocalRequest>(pipe,cancellationToken:ct);if(request is null)continue;var response=await runtime.Handle(request,ct);await JsonSerializer.SerializeAsync(pipe,response,cancellationToken:ct);await pipe.FlushAsync(ct);}catch(OperationCanceledException)when(ct.IsCancellationRequested){return;}catch(Exception ex){logger.LogWarning(ex,"Local IPC request failed");}}}
}
public static class LocalPipeAcl {public static NamedPipeServerStream Create(){var security=new PipeSecurity();security.AddAccessRule(new PipeAccessRule(new SecurityIdentifier(WellKnownSidType.BuiltinUsersSid,null),PipeAccessRights.ReadWrite,AccessControlType.Allow));security.AddAccessRule(new PipeAccessRule(new SecurityIdentifier(WellKnownSidType.LocalSystemSid,null),PipeAccessRights.FullControl,AccessControlType.Allow));return NamedPipeServerStreamAcl.Create("GManager.Client",PipeDirection.InOut,1,PipeTransmissionMode.Byte,PipeOptions.Asynchronous,4096,4096,security);}}
